"""Fourteen source-read compliance questions. Initial JIS mistake retained separately."""
import json,sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[2]/'scripts'))
from common import ROOT,read_csv
by={r['question_id']:r for r in read_csv('data/questions.csv')};items=[]
def add(q,stem,conditions,values,reasons,answer,solution,core,knowledge,theories,concept='concept_031',discipline='apt_4',law=True,citations=(),figure=False):
 r=by[q];assert len(values)==len(reasons)==5
 items.append(dict(question_id=q,source_sha256=r['source_sha256'],stem=stem,summary=stem,conditions=conditions,choices={str(i):dict(value=v,verdict='設問条件に一致' if i==answer else '設問条件に不一致',reason=w) for i,(v,w) in enumerate(zip(values,reasons),1)},figures='原典画像で問題幹・条件・否定・全5肢と全組合せセルを確認。'+('JISマークは左が現行、右が旧であり、本文の説明と逆。公式機関の画像とも照合。' if q=='R06-REG-APT-12' else '設問固有の模式図なし。'),ambiguity='',evidence=[f'extracted/pages/{r["source_year_directory"]}/aptitude/page_{p:03}.png' for p in range(int(r['source_page']),int(r['source_page_end'])+1)],core_concept=core,required_knowledge=knowledge,solution=solution,independent_answer=str(answer),answer_reason=solution,learning_points=core+'について、対象・要件・例外・時点を分け、類似用語や無条件の断定を避ける。',theory_references=theories,discipline_id=discipline,concept_id=concept,classification_reason='原典の全条件・全肢から'+core+'を中心に分類。'+('法令一般ではなく倫理原理・学会行動規範の問題としてapt_4からapt_5へ修正。' if discipline=='apt_5' else ''),calculation='false',figure=str(figure).lower(),law=str(law).lower(),evaluation=dict(knowledge_novelty='3',reasoning_steps='2',calculation_load='0',figure_reading='2' if q=='R06-REG-APT-12' else '1' if figure else '0',difficulty='3',difficulty_reason='専門外の制度の定義・要件・例外、出題当時の法令と現在の制度、組合せ表を区別して判断する。'),citations=list(citations),foundationality='high',transferability='high'))
def t(*s):return ['theory:compliance:'+x for x in s]
def table_reasons(values,actual,letters):
 return ['全項の判断に一致する。' if v==actual else '・'.join(x for x,a,b in zip(letters,actual.split('／'),v.split('／')) if a!=b)+'の正誤が違う。各記述の定義・条件を先に判定してから表に対応させる。' for v in values]
add('H23-REG-APT-15','社会的合意を形成する際の進行役・専門家・第三者の役割から、不適切な説明を選ぶ。',{'方向':'最も不適切なもの。','状況':'利害・価値観の異なる関係者間で社会的合意を形成する。'},['業務担当技術者自身が、あらゆる問題に対応する進行役となる。','技術的役割と会議進行・意見調整の役割を分けて検討する。','関係者とその利害を把握する。','中立な第三者の支援を得る。','進行支援の必要性を事前評価する。'],['担当者は事業への利害も持つ。専門知識だけで中立な進行能力やあらゆる対立の処理を保証できない。','科学技術の助言と公正な発言機会の確保は異なる能力・役割である。','表面の賛否だけでなく、守りたい利益や懸念を把握して調整する。','中立性を担保した第三者は手続の公正さを支援し得る。','関係者・対立点・実施可能性を調べて適切な支援を設計する。'],1,'合意形成は専門家が一方的に正解を説明する行為ではなく、情報・利害・価値・手続を調整する過程である。担当者の専門性と進行役の中立性・能力を同一視した1が不適切である。第三者を置けば必ず全員一致するという意味でもない。','合意形成における専門助言と中立な手続支援','関係者分析、利害、進行役、第三者の中立性、技術的判断と価値判断。',t('consensus'),concept='concept_030',law=False,citations=['mlit_mediation2006','mlit_pi_thirdparty'])
add('H27-REG-APT-10','公共・民間入札の契約方式と談合への法的対応から、不適切な説明を選ぶ。',{'時点':'平成27年の制度。','方向':'最も不適切なもの。'},['公共調達は一般競争入札が基本である。','法定条件では随意契約が認められる。','入札談合に行政処分と刑事罰が科され得る。','官製談合への職員の関与に刑事罰の制度がある。','民間事業者による入札の談合は独占禁止法等に抵触しない。'],['国の会計法上、一般競争を原則とする。地方公共団体等の具体的根拠は各制度に従う。','性質・目的が競争を許さない、緊急等の法定要件があり、自由に相手を選ぶ例外ではない。','独占禁止法上の措置や課徴金、刑事処罰の対象となり得る。ただし各行為・責任の要件があり、自動的に全参加者へ同じ制裁が及ぶとはしない。','官製談合防止制度には一定の職員の入札等妨害への刑事罰があり、2015年以前に施行されている。','独占禁止法は民間調達の競争制限を一律に除外しない。民間の受注調整にも実際の法的措置がある。'],5,'発注者が公的か民間かという区別と、事業者間で競争を制限したかという区別は別である。民間入札なら適法という5の断定が誤りである。公共契約の例外、競争法上の違反、職員の関与の責任も同じ制度へまとめない。','公共契約方式と発注主体に依存しない競争法規制','一般競争・随意契約、独占禁止法、不当な取引制限、行政・刑事責任、官製談合。',t('procurement','competition'),concept='fair_trade',citations=['mof_procurement2006','jftc_rules','jftc_kansei','jftc_private2018'])
add('H27-REG-APT-12','学術論文等の引用について適切な説明を選ぶ。',{'時点':'平成27年。','方向':'最も適切なもの。'},['承諾のない引用は全て著作権侵害である。','適法な引用の条件を満たせば、承諾なしに引用できる。','公表済みの著作物は自由に複製できる。','引用は学術研究目的だけに限られる。','外国語の著作物は原語のままでしか引用できない。'],['著作権法32条の要件を満たす引用という権利制限がある。','公表、公正な慣行、目的上正当な範囲などを満たす場合が対象で、出所も明示する。','公表と権利放棄は別であり、一般に無制限の複製を許さない。','報道・批評・研究その他の引用目的で、研究だけとの限定は誤り。','適法引用の範囲では43条による翻訳利用が可能であり、原語に限定されない。'],2,'引用は権利者の許諾を必要とする利用一般に対する要件付きの例外であり2が適切である。公表されたから自由という説明、引用だから量・目的を問わないという説明はともに誤る。訳文の利用も引用要件を満たす必要がある。','引用という要件付きの権利制限','著作権法32・43・48条、公表、公正な慣行、正当な範囲、出所、翻訳と翻案。',t('citation'),citations=['bunka_citation_faq','kyushu_copyright2015'])
v=['正／正／正／正','誤／誤／正／正','正／正／誤／正','正／正／誤／誤','正／誤／誤／正']
add('H28-REG-APT-06','公衆への説明責任について4記述の正誤の組を選ぶ。',{'ア':'十分な説明に基づく理解・信頼が重要。','イ':'専門知識を持たない公衆に分かるよう専門家が説明する必要がある。','ウ':'説明責任と守秘義務の双方が必要。','エ':'知る権利に応答する説明を、自分の意見の押付けと区別する。','並び':'ア／イ／ウ／エ'},v,table_reasons(v,'正／正／正／正','アイウエ'),1,'4項とも適切であり1である。イは専門外の人にも理解できる説明を行う責任で、同じ専門能力を要求したり、公衆の価値判断を無視したりする趣旨ではない。説明には理解・質問・検討の機会が伴う。守秘を無条件の隠蔽へ、説明を無制限の開示へ変えない。','専門知識の非対称性と理解可能な説明','説明責任、信頼、知る権利、秘密保持、同意と意見の押付け。',t('accountability'),concept='concept_030',law=False,citations=['ipej_ethics2011','ieej_conduct2007'],figure=True)
v=['正／正／正／誤','正／誤／誤／正','正／誤／誤／誤','正／正／正／正','誤／正／正／誤']
add('H28-REG-APT-11','知的財産権・特許の発明・実用新案の考案・ソフトウェアの4説明の組を選ぶ。',{'ア':'法令に定める権利や法律上保護される利益に係る権利を含む知的財産権の定義。','イ':'発明は自然法則を利用した技術的思想の創作のうち高度のもの。','ウ':'考案も自然法則を利用した技術的思想の創作で、高度を要求しない。','エ':'抽象的な人為的取決め・暗号作成・計算は発明に当たらず、プログラムでも自然法則を利用する必要がある。単なるプログラムリストの提示は発明に当たらない。','並び':'ア／イ／ウ／エ。平成28年。'},v,table_reasons(v,'正／正／正／正','アイウエ'),4,'4項とも基本定義に沿い4である。エの除外は抽象的な規則・数学・情報の単なる提示についてであり、暗号や算法を使う装置・ソフトウェア全般の特許を禁止するものではない。請求項全体としての自然法則の利用を判断する。発明に該当するだけで直ちに特許になるわけではなく、新規性・進歩性等も別要件である。','技術的創作と単なる規則・情報の区別','知的財産基本法2条、特許法2条、実用新案法2・3条、自然法則、ソフトウェア発明。',t('ip','invention'),citations=['ip_basic_act','jpo_patent_utility','jpo_invention_criteria'],figure=True)
add('H29-REG-APT-13','黄金律による他者への配慮と技術者の優先責任を表す空欄の組を選ぶ。',{'A':'自分が他者から与えられる何かを立場交換で考える。','B':'自分が受けることをどう判断するか。','C・D':'公衆の何を優先するか。','並び':'A／B／C／D。'},['不利益／無視／安全／人格','不道徳／許容／環境／人格','不利益／許容／安全／健康','不道徳／無視／環境／健康','不利益／許容／環境／人格'],['立場交換で不利益の許容を問うのでBが違い、優先責任のDも合わない。','Aは不利益、C・Dは安全・健康の組である。','受け手側で不利益を許容できるか考え、公衆の安全・健康を優先する。','A・B・Cが文脈と合わない。','A・Bは合うがC・Dは安全・健康である。'],3,'黄金律に基づく可逆性の点検は、自分が不利益を受ける側ならその扱いを許容できるかという問いである。技術者の公衆への優先責任は安全・健康で、3となる。自分だけが許容したことを全他者の同意へ置き換えず、異なる事情・価値観も聞く。人格や環境が重要でないという結論も導かない。','黄金律の可逆性と公衆への優先責任','立場交換、他者の価値観、安全・健康、倫理綱領。',['theory:ethics:tests','theory:ethics:public'],concept='engineering_ethics',discipline='apt_5',law=False,citations=['davis_seven_steps','ipej_ethics2011'])
add('H30-REG-APT-05','工学系学会の行動規範の前文に入る5語の組を選ぶ。',{'A':'未来につながる社会の性質。','B':'未来世代の権利。','C・D':'人類・社会に貢献すべき対象。','E':'専門家が協力する相手の見識。','並び':'A／B／C／D／E。電気学会2007年行動規範の前文に対応。'},['持続／生存／安全／健康／同様','持続／幸福／安定／安心／同様','進歩／幸福／安定／安心／同様','持続／生存／安全／健康／多様','進歩／幸福／安全／安心／多様'],['Eは同じ見識の人だけではなく、多様な見識の人々である。','B・C・D・Eが前文の保護対象・協力の意味と違う。','5語とも対応しない。技術進歩だけでは持続可能性を保証できない。','持続可能性、未来世代の生存、安全・健康、多様な見識との協同が対応する。','C・Eは合うが、A・B・Dが違う。'],4,'持続可能な社会を構築し、未来世代の生存権を確保し、安全と健康に貢献し、多様な見識を結集するという前文の構造から4である。電気技術の成果だけでなく、国際協調・権利・専門能力の限界を認識する文脈で読む。2021年改訂の倫理綱領と2007年行動規範を同一年の資料とはしない。','持続可能性・世代間責任・専門能力の限界','学会行動規範、未来世代、安全と健康、多様な見識、専門職の協同。',['theory:ethics:code'],concept='engineering_ethics',discipline='apt_5',law=False,citations=['ieej_conduct2007'])
add('H30-REG-APT-08','出題当時の公益通報者保護法について、不適切な説明を選ぶ。',{'時点':'2018年。2020年改正・2022年施行前。','方向':'最も不適切なもの。'},['不正目的でなく通報対象事実を所定の通報先へ知らせる。','保護要件を満たす通報者の解雇・不利益取扱いを防ぐ。','保護対象の労働者に公務員は含まれない。','内部・行政・その他外部で保護要件が異なる。','その他外部への通報には相当の理由と被害防止に必要な通報先、内部調査通知がない等の追加条件が求められる。'],['不正の目的を排除し、法律が定める対象事実と通報先を満たす必要がある。','通報を理由とする不利益から保護する制度で、あらゆる行為を無条件に免責するものではない。','公務員も原則として労働者に含まれるので誤り。公務員への取扱いには法の特則がある。','当時、行政への通報では相当の理由、その他外部ではさらに所定の追加条件などが必要であった。','列挙された事情は法定の選択的条件の例示である。全条件の同時成立や、必ず内部を経由する義務とは読まない。'],3,'公務員を一律に除外する3が誤りである。通報先によって保護要件が異なり、その他外部への通報には当時の3条3号の条件を確認する。原典5の「など」は例示なので、内部通報後20日経過等と急迫した生命・身体の危険を全て同時に要求するとは解さない。現在は2022年施行改正で保護対象・体制・要件が更新されている。2025年改正の主要部分は2026年12月1日施行予定であり、2026年10月10日現在の施行法と混ぜない。','公益通報の対象者・通報先別の保護要件と施行時点','公益通報者保護法2・3・7条、不正目的、相当の理由、公務員、内部・行政・外部、追加条件。',t('whistleblower'),concept='whistleblower',citations=['caa_handbook_pre2022','caa_report_current','caa_amend2020','caa_schedule2026'])
